edits.after:
/* Scoped read-only comic panels. One literal sheet, updated by the existing render. */
#procrastination{--pb-ink:#3e354b;--pb-muted:#6d6376;--pb-border:#554957;--pb-card:#fffcf8;--pb-bubble:#fff;--pb-accent:#795780;color:var(--pb-ink)}
#procrastination .pb-header{display:flex;justify-content:space-between;align-items:flex-start;gap:20px;margin:8px 0 24px}
#procrastination .pb-eyebrow{letter-spacing:.16em;font-size:11px;font-weight:800;color:var(--pb-accent)}
#procrastination h2{font-size:clamp(26px,3vw,36px);margin:8px 0 10px;letter-spacing:-.04em}
#procrastination .pb-intro{color:var(--pb-muted);font-size:14px;line-height:1.7;margin:0;max-width:620px}
#procrastinationCount{white-space:nowrap;border:1px solid var(--pb-border);background:var(--pb-card);border-radius:24px;padding:10px 15px;font-size:12px;font-weight:700}
#procrastination .pb-legend{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:20px;font-size:12px;color:var(--pb-muted)}
#procrastination .pb-legend span{padding:6px 10px;background:var(--pb-card);border-radius:8px}
#procrastinationBoard{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}
